import { expect, type Page } from "@playwright/test";

export const IPAD = { viewport: { width: 820, height: 1180 }, hasTouch: true, isMobile: false, userAgent: "Mozilla/5.0 (iPad; CPU OS 18_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.0 Mobile/15E148 Safari/604.1" };

/** Waits until demo media exists so renders can run (generated by the embedded worker on boot). */
export async function waitForDemoMedia(page: Page) {
  await expect
    .poll(async () => (await page.request.get("/api/media/stream/demo-C009", { headers: { Range: "bytes=0-10" } })).status(), { timeout: 120_000, intervals: [2000] })
    .toBe(206);
}

export async function gotoStage(page: Page, name: string) {
  await page.getByRole("navigation", { name: "Reel stages" }).getByRole("button", { name }).click();
}
